exec('import csv\nimport html\nimport os\nfrom datetime import datetime\nfrom zoneinfo import ZoneInfo\n\nimport pandas as pd\nimport requests\n\nPARIS = ZoneInfo("Europe/Paris")\nnow = datetime.now(PARIS)\ntoday = now.strftime("%Y-%m-%d")\nlabel = os.environ.get("REPORT_LABEL", now.strftime("%H:%M"))\n\n\ndef read_csv(path):\n    if not os.path.exists(path) or os.path.getsize(path) == 0:\n        return []\n    with open(path, encoding="utf-8") as handle:\n        return list(csv.DictReader(handle))\n\n\ndef fnum(value):\n    try:\n        return f"{float(value):.2f}"\n    except (TypeError, ValueError):\n        return "N/A"\n\n\ndef pts(value):\n    try:\n   if not value:\n return None\n     timestamp = pd.Timestamp(value)\n if pd.isna(timestamp):\n return None     if timestamp.tzinfo is None:\n            return timestamp.tz_localize("Europe/Paris")\n        return timestamp.tz_convert("Europe/Paris")\n    except Exception:\n        return None\n\n\ndef age_days(value):\n    try:\n        entry_date = datetime.strptime(value, "%Y-%m-%d").date()\n        return max(0, (now.date() - entry_date).days)\n    except (TypeError, ValueError):\n        return 0\n\n\ndef esc(value):\n    return html.escape(str(value or ""))\n\n\ndecisions = read_csv("intraday_decisions.csv")\npositions = read_csv("virtual_portfolio.csv")\ncash_rows = read_csv("portfolio_cash.csv")\nhealth_rows = read_csv("monitor_health.csv")\ncash = cash_rows[0] if cash_rows else {}\nhealth = health_rows[0] if health_rows else {}\n\nactive = {\n    line.strip()\n    for line in open("stocks.txt", encoding="utf-8")\n    if line.strip()\n}\n\ntoday_decisions = [\n    row\n    for row in decisions\n    if row.get("ticker") in active and row.get("session_date") == today\n]\n\nlatest = {}\nfor row in today_decisions:\n    ticker = row["ticker"]\n    timestamp = pts(row.get("decision_time", ""))\n    stamp = timestamp.timestamp() if timestamp is not None else 0\n    if ticker not in latest or stamp > latest[ticker][0]:\n        latest[ticker] = (stamp, row)\n\ncurrent = [item[1] for item in latest.values()]\nconfirmed = sorted(\n    [row for row in current if row.get("decision") in ("ACHAT CONFIRME", "ACHAT REACTIVE")],\n    key=lambda row: row.get("ticker", ""),\n)\nwatching = sorted(\n    [\n        row\n        for row in current\n        if row.get("next_state") == "SURVEILLANCE CATALYSEUR"\n        and row.get("reason") != "Aucune confirmation pendant une heure"\n    ],\n    key=lambda row: row.get("ticker", ""),\n)\nexpired = sorted(\n    [\n        row\n        for row in current\n        if row.get("decision") == "EXPIRE"\n        or row.get("reason") == "Aucune confirmation pendant une heure"\n    ],\n    key=lambda row: row.get("ticker", ""),\n)\npending = sorted(\n    [row for row in current if row.get("decision") == "EN ATTENTE"],\n    key=lambda row: row.get("ticker", ""),\n)\n\nlines = [\n    f"<b>📊 RAPPORT INTRADAY {esc(label)}</b>",\n    f"📅 {now.strftime(\'%d/%m/%Y\')} | Heure de Paris",\n    "",\n]\n\nlast_success = pts(health.get("last_success_paris", ""))\nfreshness_source = "monitor_health.csv"\n\nif last_success is None:\n    known_times = [pts(row.get("decision_time", "")) for row in today_decisions]\n    known_times = [timestamp for timestamp in known_times if timestamp is not None]\n    last_success = max(known_times) if known_times else None\n    freshness_source = "dernière décision connue"\n\nif last_success is None:\n    lines.extend([\n        "<b>⚪ FRAÎCHEUR DES DONNÉES : INDISPONIBLE</b>",\n        "Aucun contrôle réussi horodaté disponible.",\n        "",\n    ])\nelse:\n    freshness_minutes = max(\n        0,\n        (now - last_success.to_pydatetime()).total_seconds() / 60,\n    )\n    if freshness_minutes <= 10:\n        freshness_icon = "🟢"\n        freshness_state = "À JOUR"\n    elif freshness_minutes <= 20:\n        freshness_icon = "🟠"\n        freshness_state = "RETARDÉE"\n    else:\n        freshness_icon = "🔴"\n        freshness_state = "SURVEILLANCE INTERROMPUE"\n\n    lines.extend([\n        f"<b>{freshness_icon} FRAÎCHEUR : {freshness_state}</b>",\n        f"Dernière actualisation : {last_success.strftime(\'%d/%m/%Y à %H:%M\')} Paris",\n        f"Âge estimé : {freshness_minutes:.0f} min | Source : {freshness_source}",\n        "",\n    ])\n\nlines.extend([\n    "<b>━━━━━━━━━━━━━━━━━━</b>",\n    "<b>✅ DÉCISIONS DU JOUR</b>",\n    "<b>━━━━━━━━━━━━━━━━━━</b>",\n])\n\nif confirmed:\n    for row in confirmed:\n        timestamp = pts(row.get("decision_time", ""))\n        decision_time = timestamp.strftime("%H:%M Paris") if timestamp is not None else "heure inconnue"\n        currency = "EUR" if row["ticker"].endswith((".PA", ".AS")) else "USD"\n        lines.extend([\n            "",\n            f"<b>{esc(row[\'ticker\'])} | {esc(row[\'decision\'])}</b>",\n            f"Décision : {decision_time}",\n            f"Prix : {fnum(row.get(\'decision_close\'))} {currency} | VWAP : {fnum(row.get(\'vwap\'))}",\n            f"OR haut : {fnum(row.get(\'opening_range_high\'))} | OR bas : {fnum(row.get(\'opening_range_low\'))}",\n            f"Motif : {esc(row.get(\'reason\'))}",\n        ])\nelse:\n    lines.append("Aucune décision confirmée aujourd’hui.")\n\nlines.extend([\n    "",\n    "<b>━━━━━━━━━━━━━━━━━━</b>",\n    "<b>👀 DOSSIERS DU JOUR</b>",\n    "<b>━━━━━━━━━━━━━━━━━━</b>",\n])\n\nif watching:\n    for row in watching:\n        lines.extend([\n            "",\n            f"<b>{esc(row[\'ticker\'])} | SURVEILLANCE CATALYSEUR</b>",\n            f"OR haut : {fnum(row.get(\'opening_range_high\'))} | Motif : {esc(row.get(\'reason\'))}",\n        ])\n\nif expired:\n    for row in expired:\n        lines.extend([\n            "",\n            f"<b>⌛ {esc(row[\'ticker\'])} | SETUP EXPIRÉ</b>",\n            "Aucune confirmation dans le délai prévu. Aucun achat.",\n        ])\n\nif pending:\n    lines.extend([\n        "",\n        "<b>⏳ EN ATTENTE</b>",\n        ", ".join(esc(row["ticker"]) for row in pending),\n    ])\n\nif not watching and not expired and not pending:\n    lines.append("Aucun autre dossier actif aujourd’hui.")\n\nlines.extend([\n    "",\n    "<b>━━━━━━━━━━━━━━━━━━</b>",\n    "<b>💼 PORTEFEUILLE VIRTUEL</b>",\n    "<b>━━━━━━━━━━━━━━━━━━</b>",\n])\n\nif positions:\n    for position in positions:\n        status = position.get("status", "")\n        currency = position.get("currency", "EUR")\n        quantity = esc(position.get("quantity"))\n        duration_days = age_days(position.get("entry_date", ""))\n        duration = f"{duration_days} jour" + ("s" if duration_days != 1 else "")\n        latent_pnl = float(position.get("unrealized_pnl_eur") or 0)\n        realized_pnl = float(position.get("realized_pnl_eur") or 0)\n\n        if status == "OPEN":\n            sign = "+" if latent_pnl >= 0 else ""\n            icon = "🟢" if latent_pnl >= 0 else "🔴"\n            lines.extend([\n                "",\n                f"<b>✅ {esc(position[\'ticker\'])} | OUVERT</b>",\n                f"Depuis : {esc(position.get(\'entry_date\'))} | Durée : {duration}",\n                f"Quantité : {quantity} action(s)",\n                f"Entrée : {fnum(position.get(\'entry_price\'))} {currency} | Dernier : {fnum(position.get(\'last_price\'))} {currency}",\n                f"Coût total : {fnum(position.get(\'total_buy_cost_eur\'))} EUR | Valeur : {fnum(position.get(\'market_value_eur\'))} EUR",\n                f"{icon} PnL net estimé : <b>{sign}{fnum(latent_pnl)} EUR</b>",\n                f"🎯 Objectif : {fnum(position.get(\'target_price\'))} {currency}",\n                f"🛡 Stop : {fnum(position.get(\'stop_price\'))} {currency}",\n            ])\n        elif status == "CLOSED":\n            sign = "+" if realized_pnl >= 0 else ""\n            icon = "🟢" if realized_pnl >= 0 else "🔴"\n            lines.extend([\n                "",\n                f"<b>❌ {esc(position[\'ticker\'])} | FERMÉ</b>",\n                f"Entrée : {fnum(position.get(\'entry_price\'))} {currency} | Sortie : {fnum(position.get(\'exit_price\'))} {currency}",\n                f"{icon} PnL réalisé : <b>{sign}{fnum(realized_pnl)} EUR</b>",\n                f"Motif : {esc(position.get(\'exit_reason\'))}",\n            ])\nelse:\n    lines.append("Aucune position virtuelle.")\n\ninitial_capital = float(cash.get("initial_capital_eur") or 3000)\navailable_cash = float(cash.get("available_cash_eur") or 0)\ninvested_cost = float(cash.get("invested_cost_eur") or 0)\nmarket_value = float(cash.get("market_value_eur") or 0)\nrealized_pnl = float(cash.get("realized_pnl_eur") or 0)\nunrealized_pnl = float(cash.get("unrealized_pnl_eur") or 0)\nfees_paid = float(cash.get("fees_paid_eur") or 0)\ntotal_equity = float(cash.get("total_equity_eur") or available_cash + market_value)\ntotal_pnl = total_equity - initial_capital\ntotal_pct = 100 * total_pnl / initial_capital if initial_capital else 0\nsign = "+" if total_pnl >= 0 else ""\nicon = "🟢" if total_pnl >= 0 else "🔴"\n\nlines.extend([\n    "",\n    "<b>━━━━━━━━━━━━━━━━━━</b>",\n    "<b>💶 CAPITAL ET LIQUIDITÉS</b>",\n    "<b>━━━━━━━━━━━━━━━━━━</b>",\n    "",\n    f"Capital initial : {fnum(initial_capital)} EUR",\n    f"Liquidités : <b>{fnum(available_cash)} EUR</b>",\n    f"Capital engagé : {fnum(invested_cost)} EUR",\n    f"Valeur des positions : {fnum(market_value)} EUR",\n    f"Frais payés : {fnum(fees_paid)} EUR",\n    f"PnL réalisé : {realized_pnl:+.2f} EUR",\n    f"PnL latent net : {unrealized_pnl:+.2f} EUR",\n    "",\n    f"<b>Equity nette : {fnum(total_equity)} EUR</b>",\n    f"{icon} Résultat global : <b>{sign}{fnum(total_pnl)} EUR ({sign}{fnum(total_pct)} %)</b>",\n    "",\n    "<i>Paper trading uniquement. Aucun ordre réel.</i>",\n])\n\nmessage = "\\n".join(lines)\nresponse = requests.post(\n    "https://api.telegram.org/bot" + os.environ["TELEGRAM_BOT_TOKEN"] + "/sendMessage",\n    data={\n        "chat_id": os.environ["TELEGRAM_CHAT_ID"],\n        "text": message,\n        "parse_mode": "HTML",\n    },\n    timeout=30,\n)\nprint("Rapport Telegram :", response.status_code, response.json().get("ok"))\nprint(response.text if not response.json().get("ok") else "Rapport envoyé")\n')
